           question: "Can scratching furniture be prevented?",
           answer:
             "Scratching is normal and healthy. Offer sturdy posts near favorite furniture, reward use of the posts, and protect furniture while your cat learns the preferred spot."
         },
         {
           id: "whiskers",
           question: "What are whiskers for?",
           answer:
             "Whiskers are sensitive touch sensors that help cats judge spaces, detect air movement, and navigate in low light. Avoid trimming them because that can disorient a cat."
         },
         {
           id: "indoors",
           question: "How can indoor cats stay enriched?",
           answer:
             "Use daily play, window perches, puzzle feeders, climbing spaces, hiding spots, and safe scent exploration. Rotating toys keeps familiar objects interesting."
         }
       ];

       function FAQItem({ id, question, answer }) {
         const item = document.createElement("div");
         item.className = "example";

         const heading = document.createElement("h2");
         const button = document.createElement("button");
         const panel = document.createElement("div");
         const paragraph = document.createElement("p");
         const icon = document.createElement("span");

         button.type = "button";
         button.className = "question-button";
         button.id = `question-${id}`;
         button.setAttribute("aria-expanded", "false");
         button.setAttribute("aria-controls", `answer-${id}`);
         button.append(document.createTextNode(question));

         icon.className = "icon";
         icon.setAttribute("aria-hidden", "true");
         icon.textContent = "+";
         button.append(icon);

         panel.id = `answer-${id}`;
         panel.className = "details";
         panel.setAttribute("aria-labelledby", button.id);
         panel.hidden = true;

         paragraph.textContent = answer;
         panel.append(paragraph);
         heading.append(button);
         item.append(heading, panel);

         button.addEventListener("click", () => {
           const isOpen = button.getAttribute("aria-expanded") === "true";
           button.setAttribute("aria-expanded", String(!isOpen));
           panel.hidden = isOpen;
         });

         button.addEventListener("keydown", (event) => {
           if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
             button.setAttribute("aria-expanded", "false");
             panel.hidden = true;
           }
         });

         return item;
       }

       function FAQPage({ items }) {
         const fragment = document.createDocumentFragment();
         items.forEach((item) => fragment.append(FAQItem(item)));
         return fragment;
       }

       document.getElementById("faq-root").append(FAQPage({ items: faqs }));
     </script>
   </body>
 </html>

