  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>

    <div class="page-shell">
      <header class="hero">
        <p class="eyebrow">Feline field guide</p>
        <h1>Cat FAQ</h1>
        <p class="intro">
          Quick answers for curious cat people, from purring and naps to whiskers,
          scratching, and safe indoor enrichment.
        </p>
      </header>

      <main id="maincontent" tabindex="-1">
        <div id="faq-root" class="faq-list" aria-label="Frequently asked questions about cats">
          <div class="example">
            <h2>
              <button class="question-button" type="button" id="question-purr" aria-expanded="true" aria-controls="answer-purr">
                Why do cats purr?
                <span class="icon" aria-hidden="true">+</span>
              </button>
            </h2>
            <div class="details" id="answer-purr" aria-labelledby="question-purr">
              <p>
                Cats often purr when they feel relaxed, but they can also purr to self-soothe when stressed or
                uncomfortable. Context, body language, and appetite help tell the difference.
              </p>
            </div>
          </div>

          <div class="example">
            <h2>
              <button class="question-button" type="button" id="question-sleep" aria-expanded="true" aria-controls="answer-sleep">
                How much sleep do cats need?
                <span class="icon" aria-hidden="true">+</span>
              </button>
            </h2>
            <div class="details" id="answer-sleep" aria-labelledby="question-sleep">
              <p>
                Most adult cats sleep 12 to 16 hours a day, and kittens or senior cats may sleep even more. Short
                bursts of play before meals can help match their natural hunt-eat-rest rhythm.
              </p>
            </div>
          </div>

          <div class="example">
            <h2>
              <button class="question-button" type="button" id="question-knead" aria-expanded="true" aria-controls="answer-knead">
                Why do cats knead blankets or people?
                <span class="icon" aria-hidden="true">+</span>
              </button>
            </h2>
            <div class="details" id="answer-knead" aria-labelledby="question-knead">
              <p>
                Kneading is a comforting behavior that begins in kittenhood. Adult cats may knead soft surfaces when
                they feel safe, content, or ready to settle down.
              </p>
            </div>
          </div>

          <div class="example">
            <h2>
              <button class="question-button" type="button" id="question-scratching" aria-expanded="true" aria-controls="answer-scratching">
                Can scratching furniture be prevented?
                <span class="icon" aria-hidden="true">+</span>
              </button>
            </h2>
            <div class="details" id="answer-scratching" aria-labelledby="question-scratching">
              <p>
                Scratching is normal and healthy. Offer sturdy posts near favorite furniture, reward use of the posts,
                and protect furniture while your cat learns the preferred spot.
              </p>
            </div>
          </div>

          <div class="example">
            <h2>
              <button class="question-button" type="button" id="question-whiskers" aria-expanded="true" aria-controls="answer-whiskers">
                What are whiskers for?
                <span class="icon" aria-hidden="true">+</span>
              </button>
            </h2>
            <div class="details" id="answer-whiskers" aria-labelledby="question-whiskers">
              <p>
                Whiskers are sensitive touch sensors that help cats judge spaces, detect air movement, and navigate in
                low light. Avoid trimming them because that can disorient a cat.
              </p>
            </div>
          </div>

          <div class="example">
            <h2>
              <button class="question-button" type="button" id="question-indoors" aria-expanded="true" aria-controls="answer-indoors">
                How can indoor cats stay enriched?
                <span class="icon" aria-hidden="true">+</span>
              </button>
            </h2>
            <div class="details" id="answer-indoors" aria-labelledby="question-indoors">
              <p>
                Use daily play, window perches, puzzle feeders, climbing spaces, hiding spots, and safe scent
                exploration. Rotating toys keeps familiar objects interesting.
              </p>
            </div>
          </div>
        </div>
      </main>

      <footer>
        <p>Independent questions can be opened or closed in any order.</p>
      </footer>
    </div>

    <script>
      function FAQItem(element) {
        const button = element.querySelector(".question-button");
        const panel = element.querySelector(".details");

        function setOpen(isOpen) {
          button.setAttribute("aria-expanded", String(isOpen));
          panel.hidden = !isOpen;
        }

        button.addEventListener("click", () => {
          setOpen(button.getAttribute("aria-expanded") !== "true");
        });

        button.addEventListener("keydown", (event) => {
          if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
            setOpen(false);
            button.focus();
          }
        });

        setOpen(false);

        return { element, setOpen };
      }

      function FAQPage(root) {
        const items = [...root.querySelectorAll(".example")].map((element) => FAQItem(element));
        return { root, items };
      }

      FAQPage(document.getElementById("faq-root"));
    </script>
  </body>
</html>
